            const isChanged = changed.some((candidate) => candidate === childPath || candidate.startsWith(childPath + ".") || candidate.startsWith(childPath + "["));
            if (child && typeof child === "object" && Object.keys(child).filter((k) => k !== MODEL_ID_KEY).length) {
