          --r-1: 4px; --r-2: 6px; --r-3: 8px;
          --h-toolbar: 44px; --h-tabs: 36px; --h-ptool: 38px; --h-row: 26px; --h-status: 26px;
          --dur: 140ms; --ease: cubic-bezier(.2, .7, .2, 1);

          /* Graphite sheet */
          --g0: #0e0f11;  /* stage behind the device */
          --g1: #17191c;  /* panels */
