          --line-thin: rgba(255, 255, 255, .11);
          --line-thick: rgba(255, 255, 255, .22);
          --ink1: #e8eaed; --ink2: #a9aeb5; --ink3: #8d939b;
          /* Selection, focus, primary actions and redlines — nothing else. */
