        .toolbar {
          container: bar / inline-size;
          display: flex; align-items: center; gap: var(--sp-3); min-width: 0; padding: 0 var(--sp-2) 0 var(--sp-3);
          background: var(--g2); border-bottom: 1px solid var(--line-thin);
